// ===== 08-matcap-packs: матчепы отдельных пачек предметов =====
// Картинки из библиотеки nidorx/matcaps, выбор владельца 2026-08-18:
//   машинки — «686B73_2A2B2D_D5D9DD_B0B3BC» 256px, сила 0.35 (вторая проба:
//              первый «металл матовый» 555555_… владелец забраковал —
//              на полной силе он темнил втрое, «чет все не очень»);
//   еда     — «796D6B_DED3CB_C6BAB1_ADA09B» 256px, сила 0.6, контраст 1.8,
//              усиление 1.556 (выбор владельца из пяти показанных).
// Файлы и их источники — «3d assets/matcap/nidorx/» + ИСТОЧНИКИ.txt.
// ⚠️ У БИБЛИОТЕКИ НЕТ ЛИЦЕНЗИИ (её README: файлы собраны с разных сайтов,
// авторов установить не удалось). Для примерки неважно; решение «везти ли
// конкретный файл в поставку» — за владельцем.
//
// ⚠️⚠️ ДО ЭТОГО ВСЕ ТЕКСТУРНЫЕ МОДЕЛИ ДЕЛИЛИ ОДИН ПОЧТИ БЕЛЫЙ МАТЧЕП, И ЭТО
// БЫЛО НАМЕРЕННО: шейдер УМНОЖАЕТ матчеп на атлас, поэтому насыщенный матчеп
// «пережимает» авторскую раскраску — предмет темнеет и забирает тон матчепа.
// Это не дефект правки, а её физика; числа замерены и названы владельцу.
//
// ⚠️⚠️ ДВЕ ГРАБЛИ ВНЕШНЕГО МАТЧЕПА, ОБЕ ПОЙМАНЫ ЗАМЕРОМ, А НЕ ЧТЕНИЕМ:
// (1) АЛЬФА У НАС — ЭТО БЕЛЫЙ БЛИК. В `matcapSpecPatch` (10-stage) стоит
//     `... + vec3( matcapColor.a )`, и у процедурных матчепов блик запечён
//     именно в альфу. У любого библиотечного PNG альфа = 255 ВЕЗДЕ, то есть
//     ко всей поверхности прибавляется единица: портреты машинок дали
//     яркость 255 при насыщенности 0 против 128-157 и 0.15-0.43 на базе.
//     ⛔ Лопасти (06) и бомба (07) этим НЕ болеют — их материалы идут МИМО
//     патча, поэтому «у владельца PNG сработал» не является доводом.
// (2) ОБНУЛЯТЬ АЛЬФУ В КАНВАСЕ НЕЛЬЗЯ. Канвас хранится С ПРЕМНОЖЕНИЕМ, и при
//     альфе 0 браузер отдаёт нулевой RGB — машинки почернели (яркость 0 при
//     целом силуэте). Сырые байты `DataTexture` премножения не знают, и это
//     тот же путь, которым живут процедурные матчепы.
// ⚠️ РЯДЫ ПЕРЕВОРАЧИВАЕМ РУКАМИ: у текстуры из картинки `flipY` включён, у
// `DataTexture` — нет. Без переворота блик уехал бы сверху вниз.
// ⚠️ Сами файлы в «3d assets» остаются байт-в-байт библиотечными: перевод в
// нашу конвенцию делает КОД, и потому он виден.
// ⚠️ НОМЕР < 20 — как у 06 и 07: функции хойстятся, а `const` старших модулей
// в TDZ для top-level кода младших (инцидент 2026-08-13).
// ⚠️ ЦЕНА: машинки 15 КБ -> ~20 КБ base64, еда 64 КБ -> ~85 КБ.
// ⚠️⚠️ КРУГЛЫМ ПРЕДМЕТАМ ВАЖЕН ЦЕНТР МАТЧЕПА, А НЕ ЕГО СРЕДНЯЯ. Передняя,
// обращённая к камере сторона шара берёт цвет из СЕРЕДИНЫ картинки, поэтому
// матчеп с тёмным центром сажает фрукту чёрную дыру (замер: «515151_DCDCDC…»
// дал дыру в апельсине и морковке, «636D6C_D4E7ED…» — бурое пятно снизу).
// У машинок этого нет: там плоские панели, центр матчепа почти не работает.
// Отсюда правило отбора: фруктам — по светлой середине, а не по яркости.
// ⛔ Первый вариант «660505_F2B090…» (красный) владельцем отклонён: он не
// давал материал, а перекрашивал апельсин в вишню.
const PACK_MATCAP_SRC = { car: null, food: null, animal: null };   // заполняется в конце файла
const _packMatcapTex = {}, _packMatcapRaw = {};
// ⚠️⚠️ СИЛА — ЭТО СМЕШИВАНИЕ С БЕЛЫМ, И БЕЗ НЕЁ БИБЛИОТЕЧНЫЙ МАТЧЕП РАБОТАЕТ
// ЗАТЕМНИТЕЛЕМ, А НЕ МАТЕРИАЛОМ. Шейдер умножает матчеп на атлас, а белый —
// это тождество: k=0 даёт сегодняшнюю картинку, k=1 — матчеп в полную силу.
// Замер полной силы: машинки 128-157 -> 25-46 яркости (втрое темнее), у еды
// красный матчеп ещё и перекрашивал апельсин в вишню. Вердикт владельца на
// полной силе — «чет все не очень», отсюда и ручка.
const PACK_MATCAP_MIX = { car: 0.6, food: 0.6, animal: 0.6 };
// ⚠️ УСИЛЕНИЕ — ОТВЕТ НА «МЕТАЛЛ, НО НЕ ТЕМНЕЕ». Матчеп множится, поэтому любой
// не-белый снижает экспозицию; усиление возвращает её обратно, а перепад
// (то, что и читается металлом) остаётся. Клампится по 255: пересвет уходит
// в белый блик, что для металла честно.
// ⚠️ УСИЛЕНИЕ МАШИНОК ВЫВЕДЕНО ЗАМЕРОМ, А НЕ НА ГЛАЗ: матчеп на силе 0.6
// давал экспозицию ×0.54 от нынешней, 1.842 возвращает её к ×0.98.
const PACK_MATCAP_GAIN = { car: 2.002, food: 1.556, animal: 1.503 };
// ⚠️ КОНТРАСТ — «ЯВНЫЙ МЕТАЛЛ БЕЗ ПОТЕРИ ЯРКОСТИ». Растягиваем матчеп вокруг
// его СОБСТВЕННОЙ средней: светлое светлее, тёмное темнее, средняя на месте —
// значит экспозиция предмета не уезжает, а перепад (то, что и читается
// металлом) растёт. Отличается от усиления: усиление двигает СРЕДНЮЮ, контраст
// её сохраняет.
// машинки: 1.8 — ВЫБОР ВЛАДЕЛЬЦА из лесенки 1 / 1.8 / 2.6 / 3.4, снятой
// замером (перепад +5% при экспозиции ×0.93). Усиление 2.002 пересчитано
// под эту ступень: растяжка упирается в ноль на тёмной стороне и сама
// роняет среднюю, поэтому усиление у каждой ступени своё.
const PACK_MATCAP_CONTRAST = { car: 1.8, food: 1.8, animal: 1.8 };
function packMatcapApply(tex, k){
  const raw = _packMatcapRaw[tex], t = _packMatcapTex[tex];
  if (!raw || !t) return false;
  const n = raw.data.length, d = new Uint8Array(n);
  const g = PACK_MATCAP_GAIN[tex] != null ? PACK_MATCAP_GAIN[tex] : 1;
  const c = PACK_MATCAP_CONTRAST[tex] != null ? PACK_MATCAP_CONTRAST[tex] : 1;
  // ОПОРА КОНТРАСТА — средняя яркость САМОГО матчепа, а не 128: у металла
  // картинка светлая, и растяжка вокруг 128 увела бы её в тень.
  let сумма = 0, точек = 0;
  for (let i = 0; i < n; i += 4){
    сумма += (raw.data[i] + raw.data[i + 1] + raw.data[i + 2]) / 3; точек++;
  }
  const опора = точек ? сумма / точек : 128;
  for (let i = 0; i < n; i += 4){
    // сперва смешивание с белым (сила), потом усиление (экспозиция)
    // порядок: контраст вокруг опоры -> смешивание с белым (сила) -> усиление
    const R = опора + (raw.data[i]     - опора) * c;
    const G = опора + (raw.data[i + 1] - опора) * c;
    const B = опора + (raw.data[i + 2] - опора) * c;
    d[i]     = Math.max(0, Math.min(255, (255 + (R - 255) * k) * g));
    d[i + 1] = Math.max(0, Math.min(255, (255 + (G - 255) * k) * g));
    d[i + 2] = Math.max(0, Math.min(255, (255 + (B - 255) * k) * g));
    d[i + 3] = 0;                       // альфа = блик, у библиотечного его нет
  }
  PACK_MATCAP_MIX[tex] = k;
  // ⚠️⚠️ ПРИ СМЕНЕ РАЗМЕРА КАРТИНКИ — ТОЛЬКО ЧЕРЕЗ dispose. three дообновляет
  // уже загруженную DataTexture ПОДКАРТИНКОЙ, поэтому картинка другого размера
  // молча не доезжает до предмета: текстура честно отдаёт новый размер, а на
  // экране остаётся старый материал. Поймано примеркой (еда не реагировала
  // НИ НА ЧТО, включая заведомо красный матчеп, пока машинки слушались) —
  // чтением кода не видно. Боевой путь этим не болел (матчеп машинок печётся
  // в сборку сразу нужного размера), но живая подмена из редактора и любая
  // будущая пачка споткнулись бы о то же самое.
  const было = t.image;
  if (было && (было.width !== raw.width || было.height !== raw.height)) t.dispose();
  t.image = { data: d, width: raw.width, height: raw.height };
  t.needsUpdate = true;
  // портреты коллекции снимаются ОДИН раз и кэшируются — без сброса музей
  // остался бы со старым материалом
  if (typeof thumbCacheDrop === 'function') thumbCacheDrop();
  return true;
}
// Одна текстура на пачку и НА ВСЮ ЖИЗНЬ: материалы создаются раньше декода и
// держат ССЫЛКУ, поэтому подменять объект нельзя — только его содержимое.
// ЖИВАЯ ЗАГРУЗКА ЛЮБОГО PNG В ПАЧКУ — примерка без пересборки (режим
// разработчика). Тем же путём проверяются кандидаты из библиотеки: иначе
// каждая проба стоила бы сборки в 10 МБ.
function packMatcapLoad(tex, src, opts){
  opts = opts || {};
  if (opts.mix  != null) PACK_MATCAP_MIX[tex]  = opts.mix;
  if (opts.gain != null) PACK_MATCAP_GAIN[tex] = opts.gain;
  if (src){
    PACK_MATCAP_SRC[tex] = src;
    delete _packMatcapRaw[tex];
    const t = _packMatcapTex[tex];
    if (!t) { packMatcapTex(tex); return true; }
    const img = new Image();
    img.onload = () => {
      const c = document.createElement('canvas');
      const w = c.width = img.width, h = c.height = img.height;
      const x = c.getContext('2d');
      x.drawImage(img, 0, 0);
      const s = x.getImageData(0, 0, w, h).data;
      const d = new Uint8Array(w * h * 4);
      for (let y = 0; y < h; y++){
        const from = (h - 1 - y) * w * 4, to = y * w * 4;
        for (let i = 0; i < w * 4; i += 4){
          d[to + i] = s[from + i]; d[to + i + 1] = s[from + i + 1];
          d[to + i + 2] = s[from + i + 2]; d[to + i + 3] = 0;
        }
      }
      _packMatcapRaw[tex] = { data: d, width: w, height: h };
      packMatcapApply(tex, PACK_MATCAP_MIX[tex]);
    };
    img.src = src;
    return true;
  }
  return packMatcapApply(tex, PACK_MATCAP_MIX[tex]);
}
function packMatcapTex(tex){
  const src = PACK_MATCAP_SRC[tex];
  if (!src) return null;
  if (_packMatcapTex[tex]) return _packMatcapTex[tex];
  // ЗАГЛУШКА 1×1: белый цвет, АЛЬФА 0 — «матчеп-тождество». До декода предметы
  // выглядят ровно как на базе, а не чёрными и не выбеленными.
  const t = new THREE.DataTexture(new Uint8Array([255, 255, 255, 0]), 1, 1, THREE.RGBAFormat);
  t.encoding = THREE.sRGBEncoding;
  t.magFilter = t.minFilter = THREE.LinearFilter;
  t.generateMipmaps = false; t.flipY = false; t.needsUpdate = true;
  const img = new Image();
  img.onload = () => {
    const c = document.createElement('canvas');
    const w = c.width = img.width, h = c.height = img.height;
    const x = c.getContext('2d');
    x.drawImage(img, 0, 0);
    const s = x.getImageData(0, 0, w, h).data;
    const d = new Uint8Array(w * h * 4);
    for (let y = 0; y < h; y++){
      const from = (h - 1 - y) * w * 4, to = y * w * 4;
      for (let i = 0; i < w * 4; i += 4){
        d[to + i] = s[from + i]; d[to + i + 1] = s[from + i + 1];
        d[to + i + 2] = s[from + i + 2]; d[to + i + 3] = 0;  // альфа = блик
      }
    }
    _packMatcapRaw[tex] = { data: d, width: w, height: h };
    packMatcapApply(tex, PACK_MATCAP_MIX[tex] != null ? PACK_MATCAP_MIX[tex] : 1);
  };
  img.src = src;
  _packMatcapTex[tex] = t;
  return t;
}
PACK_MATCAP_SRC.food = 'data:image/png;base64,';
PACK_MATCAP_SRC.car = 'data:image/png;base64,';
// ⚠️ ЗВЕРИ БЕРУТ ТУ ЖЕ КАРТИНКУ, ЧТО ЕДА (выбор владельца — «тёплый сатин»),
// и берут её ПРИСВАИВАНИЕМ: второй такой же base64 стоил бы лишние 54 КБ в
// сборке ни за что. Текстуры у пачек всё равно РАЗНЫЕ объекты — у них свои
// сила, контраст и усиление, а усиление у зверей другое (1.503 против 1.556
// у еды): множитель зависит от того, какие нормали у предметов пачки в кадре.
PACK_MATCAP_SRC.animal = PACK_MATCAP_SRC.food;
